KG42.register("edges-6d5bda60172cef3c93a64826",{"id":"S-5aaf9770feb52b94","source":"COMP-b646a091517c6af0","type":"links","target":"COMP-a1af16dd42f1ff08","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["15-multiagent_reverse_auction"],"assertions":[{"id":"15-multiagent_reverse_auction::v141-c-R009::E::v141-c-R009-E001","paper":"15-multiagent_reverse_auction","rule_id":"v141-c-R009","rule_ref":"15-multiagent_reverse_auction::v141-c-R009","record":{"edge_id":"v141-c-R009-E001","source":"coordination.local_operator","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R009-C002"],"evidence_ids":["v141-b-g01-E15"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R009-C002"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-b646a091517c6af0","target":"COMP-a1af16dd42f1ff08","source_occurrence_id":"15-multiagent_reverse_auction::v141-c-R009::V::coordination.local_operator","target_occurrence_id":"15-multiagent_reverse_auction::v141-c-R009::V::participation.prosumer","source_unit_id":"15-multiagent_reverse_auction::v141-a-M01::coordination.local_operator","target_unit_id":"15-multiagent_reverse_auction::v141-a-M01::participation.prosumer","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Aggregator invitations to DER agents in the microgrid reverse auction. | Available generators seeking participation in the microgrid's hour-ahead reverse auction. | Continued DER participation during a rebidding round of the hourly microgrid auction. | DER bidding-agent decisions about joining the next hour's auction. | The initial DER participation test in Algorithm 1 for the microgrid reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E17"]},"active":true,"source_signature":"e48ab20cc0fbac0c1a24951ff7ca2b808da86a1ac9294ae92336a5ef552635d0","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"DER supply submissions declaring available power and the next-hour price are sent to and collected by the DER aggregator. Scope: Next-hour DER bids in the hour-ahead reverse auction for the grid-connected microgrid's lumped load. The aggregator's procurement objective is to purchase the required amount of energy with the least cost. Scope: Procurement for the lumped load through the hour-ahead reverse auction in the studied grid-connected microgrid.","target_definition":"Participation by available microgrid generators requires yellow-pages registration, the stated admission requirement for this local market. Scope: Available generators seeking participation in the microgrid's hour-ahead reverse auction. Condition: The generator seeks to participate in bidding processes. The aggregator coordinates DER participation by inviting registered agents to participate in the auction. Scope: Aggregator invitations to DER agents in the microgrid reverse auction. Condition: The agents are registered to the yellow pages. Base-price information supplied by cost-function or state-of-charge agents informs the DER bidding agent's decision whether to participate. Scope: DER bidding-agent decisions about joining the next hour's auction. Condition: The DER is available for the next hour. Algorithm 1 conditions DER bidding participation on the comparison with the utility base-price signal: bidders submit when their base price is lower and otherwise drop without participating. Scope: The initial DER participation test in Algorithm 1 for the microgrid reverse auction. Condition: The DER base price is lower than the utility base price; the alternative branch specifies nonparticipation. A bidder that is no longer interested in the new submission drops out and quits the auction for that particular hour. Scope: Continued DER participation during a rebidding round of the hourly microgrid auction. Condition: Supply exceeds demand, prompting a lower-price bidding request, and the bidder is no longer interested in the new submission.","constraints":[{"constraint_id":"v141-c-R009-C002","kind":"procedural","role":"core","statement":"The aggregator coordinates DER participation by inviting registered agents to participate in the auction. Scope: Aggregator invitations to DER agents in the microgrid reverse auction. Condition: The agents are registered to the yellow pages.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E15"]}],"evidence":[{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-1b3df4bc99-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"The aggregator manages the communication and the infor- his mation exchange between participants to ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The aggregator manages the communication and the information exchange between participants to minimize the cost of the electricity to be purchased for the lumped load. The aggregator agent is the main entity operating the auction process. Its task is to solicit bids form the agents registered to the yellow pages, and to invite them to participate in the auction. The ultimate goal is to purchase the required amount of power with the lowest cost. DERs submit bids to the DER aggregator, declaring the power available to sell and the price for the next hour. Each DER has a generation capacity, marginal cost, and availability."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Aggregator invitations to DER agents in the microgrid reverse auction. | Available generators seeking participation in the microgrid's hour-ahead reverse auction. | Continued DER participation during a rebidding round of the hourly microgrid auction. | DER bidding-agent decisions about joining the next hour's auction. | The initial DER participation test in Algorithm 1 for the microgrid reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E17"]},"source_record":{"edge_id":"v141-c-R009-E001","source":"coordination.local_operator","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R009-C002"],"evidence_ids":["v141-b-g01-E15"]},"paper_scope_note":"Registration, auction invitation, bid, eligibility, and final power command are checked separately; the utility base price differs from the DER private base price; the general single-winner and two-winner cases are not combined into the same condition."}}],"assertion_ids":["15-multiagent_reverse_auction::v141-c-R009::E::v141-c-R009-E001"]});
